// Lightweight loader that injects the real ethers.js build from a CDN.
// Usage: import { loadEthers } from 'public/lib/ethers.min.js';

import { loadScript } from 'wix-window';

const ETHERS_CDN =
  'https://cdn.jsdelivr.net/npm/ethers@6.11.1/dist/ethers.umd.min.js';

let ethersPromise = null;

export function loadEthers() {
  if (typeof window === 'undefined') {
    return Promise.reject(new Error('Window is required.'));
  }
  if (window.ethers) {
    return Promise.resolve(window.ethers);
  }
  if (!ethersPromise) {
    ethersPromise = loadScript(ETHERS_CDN).then(() => window.ethers);
  }
  return ethersPromise;
}
